import sys
import os

# Append (not insert) system site-packages so venv packages take priority,
# but numpy/pandas/pyarrow fall back to the system copies whose .pyd/.dll files are
# not blocked by Windows Application Control and are version-compatible (NumPy 1.26 + PyArrow 23.0).
system_site = r"C:\Users\deepa\AppData\Local\Programs\Python\Python311\Lib\site-packages"
if os.path.exists(system_site) and system_site not in sys.path:
    sys.path.append(system_site)
